var n=`1014-moo-ping`;var a=`world-1014`;var r=`TH`;var t=`southeast-asia`;var s=4;var o=116;var l={en:`Moo Ping`,ua:`Му пінг`};var g={en:`Moo Ping is a dish from Thailand prepared with pork shoulder, garlic, cilantro, light soy sauce. This is a home-scale version with measured ingredients in the individual steps where they are used. Cilantro leaves replace unavailable coriander roots in the marinade.`,ua:`Му пінг, страва кухні країни Таїланд, яку готують із таких продуктів: свиняча лопатка, часник, кінза, світлий соєвий соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Зелень кінзи замінює відсутнє в каталозі коріння коріандру.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`pork-shoulder`,750,`g`],[`garlic`,5,`clove`],[`cilantro`,20,`g`],[`light-soy-sauce`,40,`ml`],[`fish-sauce`,22,`ml`],[`palm-sugar`,28,`g`],[`coconut-milk`,110,`ml`]]},{en:`Thread the already marinated pieces on skewers, leaving small gaps for even cooking.`,ua:`Нанизайте раніше замариновані шматочки на шпажки з невеликими проміжками для рівного прогрівання.`,t:[`threading-skewers`],m:7,i:[]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:17,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cucumber`,180,`g`]]}];var d={slug:n,id:a,country:`TH`,region:t,servings:4,minutes:116,title:l,text:g,steps:h};export{r as country,d as default,a as id,o as minutes,t as region,s as servings,n as slug,h as steps,g as text,l as title};